/** A tuple-byte budget admits many small predicate pages while bounding full pages and malformed metadata. */
class LmdbPersistentAdjacencyNodeMergeCapacityTest {

	private static final int ADMISSION_ROWS = 128;
	private static final long[] UNBOUND = { -1, -1, -1, -1 };

	@TempDir
	Path directory;

	@ParameterizedTest(name = "predicates={0}, order={1}, managed={2}")
	@CsvSource({ "32,spoc,false", "32,opsc,true", "64,spoc,true", "64,opsc,false" })
	void smallPredicatePagesShareABoundedMerge(int predicates, String order, boolean managed) throws Exception {
		try (Fixture fixture = new Fixture(directory, sharedRows(predicates, 48), true);
				Txn txn = fixture.snapshot()) {
			assertThat(fixture.physicalFences(txn, fixture.adjacency.pagesDbi(), order)).hasSize(predicates);
			assertThat(fixture.physicalFences(txn, fixture.adjacency.deltasDbi(), order)).isEmpty();
			try (NativeWork work = new NativeWork(fixture.adjacency, false)) {
				assertThat(read(fixture, txn, managed, order, UNBOUND, null))
						.containsExactlyElementsOf(expected(fixture.quads, order, UNBOUND, null, null));
				assertAll(
						() -> assertThat(work.metadataReads)
								.as("small pages must not force per-row enumeration: %s", work)
								.isLessThanOrEqualTo(ADMISSION_ROWS + predicates + 6L),
						() -> assertThat(work.pageDecodes).as("only the prefix and admitted heads may decode: %s", work)
								.isLessThanOrEqualTo(ADMISSION_ROWS + predicates + 1L),
						() -> assertThat(work.pageReads).as("positioning stays bounded after admission: %s", work)
								.isLessThanOrEqualTo(3L * ADMISSION_ROWS + 4L * predicates + 16),
						() -> assertThat(work.opens).as("more predicates must not allocate more cursors: %s", work)
								.isLessThanOrEqualTo(3),
						() -> assertThat(work.deltaReads).isLessThanOrEqualTo(1));
				assertThat(work.live).isEmpty();
			}
		}
	}

	@Test
	void twentyTwoFullPagesExceedTheTupleByteBudgetAndRestoreThePendingRow() throws Exception {
		try (Fixture fixture = new Fixture(directory, sharedRows(22, LmdbPersistentAdjacency.PAGE_QUADS), true);
				Txn txn = fixture.snapshot()) {
			assertThat(fixture.physicalFences(txn, fixture.adjacency.pagesDbi(), "spoc")).hasSize(22);
			List<Q> expectedPrefix = expected(fixture.quads, "spoc", UNBOUND, null, null).subList(0, 256);
			try (NativeWork work = new NativeWork(fixture.adjacency, false)) {
				try (RecordIterator records = fixture.adjacency.scan(txn, -1, -1, -1, -1, true, "spoc")) {
					assertThat(prefix(records, 256)).containsExactlyElementsOf(expectedPrefix);
				}
				assertThat(22L * LmdbPersistentAdjacency.PAGE_QUADS * 3 * Long.BYTES).isGreaterThan(512L * 1024);
				assertThat(work.rowEntries).as("an over-budget merge must keep traversing directory rows")
						.isGreaterThanOrEqualTo(256);
				assertThat(work.metadataReads).as("the rejected byte budget is not recomputed at every row")
						.isLessThanOrEqualTo(256 + 22 + 4L);
				assertThat(work.pageDecodes).as("fallback retains the sixteen-page cache")
						.isGreaterThan(22);
				assertThat(work.predicateEntries).isLessThanOrEqualTo(22);
				assertThat(work.catalogRestores).isEqualTo(1);
				assertThat(work.opens).isLessThanOrEqualTo(3);
				assertThat(work.live).isEmpty();
			}
		}
	}

	@ParameterizedTest(name = "replacement page={0}")
	@ValueSource(booleans = { false, true })
	void anUnderstatedReservationCannotRetainAnOversizedDecodedPage(boolean replacement) throws Exception {
		int count = replacement ? 2048 : 1280;
		try (Fixture fixture = new Fixture(directory, sharedRows(1, count), true)) {
			if (replacement) {
				// Leave a 256-tuple first page followed by a 1024-tuple page without handcrafting encoded pages.
				LmdbUtil.writeTransaction(fixture.store.env, (stack, writer) -> {
					for (int ordinal = 0; ordinal < 768; ordinal++) {
						Q removed = quad(ordinal, 20);
						assertThat(fixture.adjacency.remove(writer, removed.s(), removed.p(), removed.o(), removed.c(),
								true))
										.isTrue();
						assertThat(fixture.quads.remove(removed)).isTrue();
					}
					fixture.adjacency.compact(writer, true);
					return null;
				});
			}
			understateOutgoingPredicateCount(fixture, replacement ? 256 : 1);
			try (Txn txn = fixture.snapshot()) {
				assertThat(fixture.physicalFences(txn, fixture.adjacency.pagesDbi(), "spoc")).hasSize(2);
				int delivered = replacement ? 256 : ADMISSION_ROWS;
				List<Q> expectedPrefix = expected(fixture.quads, "spoc", UNBOUND, null, null).subList(0, delivered);
				try (NativeWork work = new NativeWork(fixture.adjacency, false);
						RecordIterator records = fixture.adjacency.scan(txn, -1, -1, -1, -1, true, "spoc")) {
					assertThat(prefix(records, delivered)).containsExactlyElementsOf(expectedPrefix);
					assertThatThrownBy(records::next).isInstanceOf(SailException.class)
							.hasCauseInstanceOf(IOException.class);
					assertThat(work.live).as("a rejected initial or replacement head releases its cursor owners")
							.isEmpty();
				}
			}
		}
	}

	private static void understateOutgoingPredicateCount(Fixture fixture, long count) throws IOException {
		LmdbUtil.writeTransaction(fixture.store.env, (stack, writer) -> {
			ByteBuffer key = stack.malloc(10)
					.order(ByteOrder.BIG_ENDIAN)
					.put((byte) 2)
					.put((byte) 0)
					.putLong(20)
					.flip();
			ByteBuffer value = stack.malloc(Long.BYTES).order(ByteOrder.BIG_ENDIAN).putLong(count).flip();
			LmdbUtil.E(LMDB.mdb_put(writer, fixture.adjacency.metadataDbi(), MDBVal.malloc(stack).mv_data(key),
					MDBVal.malloc(stack).mv_data(value), 0));
			return null;
		});
	}
}
